INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-trieste-dsai', 'trieste-msc-data-science-artificial-intelligence', 'MSc Data Science and Artificial Intelligence', 'uni-university-of-trieste', 'master', 'computer-science-data', 'english', 2, 120, 'A Bachelor''s degree with at least 30 CFU in mathematics / computer-science disciplines (at least 9 CFU in mathematics) and English at B2 level are required. An Admission Board assesses curricular requirements and preparation — see the official ''How to apply'' page.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://degree.units.it/en/0320107313600001/how-apply', '2026/27', 'https://degree.units.it/en/0320107313600001/how-apply', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-pavia-harvey', 'pavia-medicine-surgery-harvey', 'Medicine and Surgery (Harvey) — Single-Cycle Master''s', 'uni-university-of-pavia', 'single_cycle', 'medicine-health', 'english', 6, 360, 'Secondary school diploma required. This is a six-year single-cycle Master''s degree taught in English with restricted access — admission is through the national admission test set by the annual ministerial call. See the official programme page for the current call.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://en.unipv.it/en/education/bachelors-and-masters-degree-programs/second-cycle-degree-course/medicine-and-surgery-0', '2026/27', 'https://en.unipv.it/en/education/bachelors-and-masters-degree-programs/second-cycle-degree-course/medicine-and-surgery-0', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-unibo-medicine', 'bologna-medicine-surgery', 'Medicine and Surgery — Single-Cycle Master''s', 'u-unibo', 'single_cycle', 'medicine-health', 'english', 6, 360, 'Secondary school diploma and English at B2 level are required. Access is restricted at national level: admission is through the entrance examination set each year by ministerial decree — see the official programme page and the annual call (degree class LM-41).', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://corsi.unibo.it/singlecycle/MedicineAndSurgery/overview', '2026/27', 'https://corsi.unibo.it/singlecycle/MedicineAndSurgery/overview', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-unitn-phd-iecs', 'trento-phd-information-engineering-computer-science', 'PhD in Information Engineering and Computer Science', 'u-unitn', 'phd', 'computer-science-data', 'english', 3, NULL, 'A Master''s degree (or a qualification giving access to PhD study) is required; candidates who will graduate by the date stated in the call may also apply. Admission is by the annual public selection (evaluation of qualifications) — most positions are covered by scholarships under the call. The programme''s official language is English.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'http://www.unitn.it/en/phd/information-engineering-and-computer-science', '2026/27', 'http://www.unitn.it/en/phd/information-engineering-and-computer-science', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-sapienza-phd-cs', 'sapienza-phd-computer-science', 'PhD in Computer Science', 'u-sapienza', 'phd', 'computer-science-data', 'english', 3, NULL, 'A Master''s degree is required. Admission is by competitive selection under Sapienza''s annual PhD call (qualifications and examination) — see the official PhD programme page for the current cycle, positions and scholarships.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://phd.uniroma1.it/web/COMPUTER-SCIENCE_nD3507_EN.aspx', '2026/27', 'https://phd.uniroma1.it/web/COMPUTER-SCIENCE_nD3507_EN.aspx', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.courses (id, slug, name, university_id, level, subject, language, duration_years, credits, requirements, tuition_note, deadline_note, official_url, academic_year, source_url, last_verified, verification_status, status) VALUES ('c-unibo-phd-dsc', 'bologna-phd-data-science-computation', 'PhD in Data Science and Computation', 'u-unibo', 'phd', 'computer-science-data', 'both', 3, 180, 'A second-level (Master''s) degree is required. Admission is by evaluation of qualifications and research proposal plus an oral examination, under the annual PhD call — see the official programme page for positions and scholarships. Working languages: English and Italian.', 'Not verified — see the university''s official fees page.', 'Check the official programme page for the current call and deadlines.', 'https://phd.unibo.it/dsc/en/phd-programme/', '2026/27', 'https://phd.unibo.it/dsc/en/phd-programme/', '2026-10-30', 'verified', 'published') ON CONFLICT (id) DO NOTHING;

